param([switch]$AutoStart)
$ErrorActionPreference="Stop"
Add-Type -AssemblyName PresentationFramework,PresentationCore,WindowsBase,System.Windows.Forms,System.Drawing
$root=(Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path
$setupScript=Join-Path $PSScriptRoot "setup-performance-center.ps1"
$startScript=Join-Path $PSScriptRoot "start-supervised-performance-center.ps1"
$controlScript=Join-Path $PSScriptRoot "supervisor-control.ps1"
$wizardScript=Join-Path $PSScriptRoot "env-wizard.ps1"
$updateScript=Join-Path $PSScriptRoot "update-performance-center.ps1"
$stopScript=Join-Path $PSScriptRoot "stop-performance-center.ps1"
$edgeScript=Join-Path $PSScriptRoot "launch-edge.ps1"
$logPath=Join-Path $root "logs\supervisor.log"
. (Join-Path $PSScriptRoot "native-operator-ui.ps1")
function Test-Backend {try{$r=Invoke-RestMethod "http://127.0.0.1:3000/api/v1/health" -TimeoutSec 2;return $r.status -eq "ok"}catch{return $false}}
function Get-Admin {try{Invoke-RestMethod "http://127.0.0.1:3000/api/v1/admin" -TimeoutSec 3}catch{$null}}
function Get-Lan {try{(Get-NetIPConfiguration|Where-Object {$_.IPv4DefaultGateway}|ForEach-Object {$_.IPv4Address.IPAddress}|Where-Object {$_ -and $_ -notmatch '^127\.|^169\.254\.'}|Select-Object -First 1)}catch{"<this-PC-IP>"}}
function Needs-Setup {(-not(Get-Command node -ErrorAction SilentlyContinue))-or(-not(Test-Path (Join-Path $root "node_modules")))-or(-not(Test-Path (Join-Path $root ".env")))-or(-not(Test-Path (Join-Path $root "apps\dashboard\dist\index.html")))}
function Run-HiddenWait($script,$arguments=@()){ $args=@('-STA','-NoProfile','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File',('"{0}"' -f $script))+$arguments; $p=Start-Process powershell.exe -ArgumentList $args -WorkingDirectory $root -WindowStyle Hidden -PassThru -Wait; return $p.ExitCode }
function Start-Supervisor {if(Test-Backend){return};Start-Process powershell.exe -ArgumentList @('-STA','-NoProfile','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File',('"{0}"' -f $startScript),'-SkipBuild') -WorkingDirectory $root -WindowStyle Hidden|Out-Null}
function Wait-Backend([bool]$wanted,[int]$seconds=40){$end=(Get-Date).AddSeconds($seconds);do{$ok=Test-Backend;if($ok -eq $wanted){return $true};Start-Sleep -Milliseconds 500;[System.Windows.Forms.Application]::DoEvents()}while((Get-Date)-lt $end);return $false}
function Version-Text {try{$p=Get-Content (Join-Path $root 'package.json') -Raw|ConvertFrom-Json;$v=$p.version}catch{$v='?'};try{$s=(git -C $root rev-parse --short HEAD 2>$null).Trim()}catch{$s='packaged'};"v$v - $s"}
function ST-State($a){if(-not$a){return 'unknown'};$t=(($a.diagnostics.serviceTitan|ConvertTo-Json -Compress -Depth 5)+' '+($a.diagnostics.browser|ConvertTo-Json -Compress -Depth 5)).ToLowerInvariant();if($t -match 'login|sign.in|auth.*required|unauthorized|forbidden|session.*expired'){return 'login-required'};if($a.diagnostics.serviceTitan.status -eq 'connected' -and $a.diagnostics.browser.connected -and $a.diagnostics.browser.serviceTitanPageFound){return 'healthy'};'degraded'}
[xml]$xaml=@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="GRMetro Performance Center" Width="1040" Height="820" MinWidth="940" MinHeight="700" WindowStartupLocation="CenterScreen" Background="#F4F7FB" FontFamily="Segoe UI" Foreground="#172033"><Window.Resources><Style x:Key="Tile" TargetType="Button"><Setter Property="Background" Value="White"/><Setter Property="BorderBrush" Value="#DCE3EC"/><Setter Property="BorderThickness" Value="1"/><Setter Property="Padding" Value="14"/><Setter Property="Margin" Value="5"/><Setter Property="HorizontalContentAlignment" Value="Left"/><Setter Property="Cursor" Value="Hand"/></Style></Window.Resources><Grid><Grid.RowDefinitions><RowDefinition Height="108"/><RowDefinition Height="*"/><RowDefinition Height="48"/></Grid.RowDefinitions><Border Background="#172033"><Grid Margin="30,0"><StackPanel VerticalAlignment="Center"><TextBlock Text="GRMetro" Foreground="#75B8F4" FontSize="13" FontWeight="SemiBold"/><TextBlock Text="Performance Center" Foreground="White" FontSize="30" FontWeight="SemiBold"/><TextBlock Text="Native backend operations - ServiceTitan - display network" Foreground="#AEBCCE" FontSize="13"/></StackPanel><StackPanel HorizontalAlignment="Right" VerticalAlignment="Center"><Border Background="#26364C" CornerRadius="15" Padding="12,6"><StackPanel Orientation="Horizontal"><Ellipse x:Name="HeaderDot" Width="8" Height="8" Fill="#F0A400" Margin="0,0,8,0"/><TextBlock x:Name="HeaderText" Text="Checking" Foreground="White" FontWeight="SemiBold"/></StackPanel></Border><TextBlock x:Name="VersionText" Foreground="#94A5BA" Margin="0,7,0,0" HorizontalAlignment="Right"/></StackPanel></Grid></Border><ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto"><StackPanel Margin="30,24"><Border Background="White" BorderBrush="#E1E7EF" BorderThickness="1" CornerRadius="15" Padding="22"><Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="300"/></Grid.ColumnDefinitions><StackPanel><TextBlock Text="SYSTEM STATUS" Foreground="#758397" FontSize="11" FontWeight="SemiBold"/><StackPanel Orientation="Horizontal" Margin="0,8,0,0"><Ellipse x:Name="StatusDot" Width="12" Height="12" Fill="#F0A400" Margin="0,8,10,0"/><TextBlock x:Name="StatusLabel" Text="Checking..." FontSize="25" FontWeight="SemiBold"/></StackPanel><TextBlock x:Name="StatusDetail" Text="Reading backend health..." Foreground="#647287" FontSize="13" Margin="22,5,0,0" TextWrapping="Wrap"/><ProgressBar x:Name="Progress" Height="4" Margin="22,12,0,0" IsIndeterminate="True" Visibility="Collapsed"/></StackPanel><StackPanel Grid.Column="1" VerticalAlignment="Center"><Button x:Name="PrimaryButton" Content="CHECKING..." Height="46" Background="#0F6CBD" Foreground="White" FontWeight="SemiBold" BorderThickness="0" IsEnabled="False"/><Button x:Name="LoginButton" Content="OPEN SERVICETITAN LOGIN" Height="38" Margin="0,8,0,0" Visibility="Collapsed"/></StackPanel></Grid></Border><Grid Margin="0,16,0,0"><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="14"/><ColumnDefinition/></Grid.ColumnDefinitions><Border Background="#EAF4FF" CornerRadius="11" Padding="16"><StackPanel><TextBlock Text="PHONE REMOTE" Foreground="#51779A" FontSize="10" FontWeight="SemiBold"/><TextBlock x:Name="RemoteUrl" FontFamily="Consolas" FontSize="12" Margin="0,5,0,0"/></StackPanel></Border><Border Grid.Column="2" Background="#F4F1FF" CornerRadius="11" Padding="16"><StackPanel><TextBlock Text="TV DISPLAY URL" Foreground="#6F5F9C" FontSize="10" FontWeight="SemiBold"/><TextBlock x:Name="DisplayUrl" FontFamily="Consolas" FontSize="12" Margin="0,5,0,0"/></StackPanel></Border></Grid><TextBlock Text="TOOLS" Foreground="#758397" FontSize="11" FontWeight="SemiBold" Margin="4,22,0,4"/><UniformGrid Columns="3"><Button x:Name="RemoteButton" Style="{StaticResource Tile}"><StackPanel><TextBlock Text="Phone Remote" FontWeight="SemiBold"/><TextBlock Text="Native access and QR" Foreground="#77869A" FontSize="11"/></StackPanel></Button><Button x:Name="AdminButton" Style="{StaticResource Tile}"><StackPanel><TextBlock Text="Admin Diagnostics" FontWeight="SemiBold"/><TextBlock Text="Open inside this app" Foreground="#77869A" FontSize="11"/></StackPanel></Button><Button x:Name="LogsButton" Style="{StaticResource Tile}"><StackPanel><TextBlock Text="Recovery Logs" FontWeight="SemiBold"/><TextBlock Text="View inside this app" Foreground="#77869A" FontSize="11"/></StackPanel></Button><Button x:Name="RefreshButton" Style="{StaticResource Tile}"><StackPanel><TextBlock Text="Refresh Data" FontWeight="SemiBold"/><TextBlock x:Name="RefreshDetail" Text="Fresh ServiceTitan sync" Foreground="#77869A" FontSize="11"/></StackPanel></Button><Button x:Name="RestartBackendButton" Style="{StaticResource Tile}"><StackPanel><TextBlock Text="Restart Backend" FontWeight="SemiBold"/><TextBlock x:Name="BackendDetail" Text="Restart backend only" Foreground="#77869A" FontSize="11"/></StackPanel></Button><Button x:Name="RestartBrowserButton" Style="{StaticResource Tile}"><StackPanel><TextBlock Text="Restart ServiceTitan" FontWeight="SemiBold"/><TextBlock x:Name="BrowserDetail" Text="Relaunch dedicated Edge" Foreground="#77869A" FontSize="11"/></StackPanel></Button><Button x:Name="UpdateButton" Style="{StaticResource Tile}"><StackPanel><TextBlock Text="Check for Updates" FontWeight="SemiBold"/><TextBlock Text="Safe pull, test and build" Foreground="#77869A" FontSize="11"/></StackPanel></Button><Button x:Name="ConfigButton" Style="{StaticResource Tile}"><StackPanel><TextBlock Text="Setup &amp; Configuration" FontWeight="SemiBold"/><TextBlock Text="Edit deployment settings" Foreground="#77869A" FontSize="11"/></StackPanel></Button><Button x:Name="FolderButton" Style="{StaticResource Tile}"><StackPanel><TextBlock Text="Program Folder" FontWeight="SemiBold"/><TextBlock Text="Open installation files" Foreground="#77869A" FontSize="11"/></StackPanel></Button></UniformGrid><TextBlock Text="LIVE ACTIVITY" Foreground="#758397" FontSize="11" FontWeight="SemiBold" Margin="4,20,0,6"/><Border Background="White" BorderBrush="#E1E7EF" BorderThickness="1" CornerRadius="11" Padding="14"><ListBox x:Name="ActivityList" BorderThickness="0" Background="Transparent" MaxHeight="130"/></Border></StackPanel></ScrollViewer><Border Grid.Row="2" Background="#EBEFF5" BorderBrush="#DDE4EC" BorderThickness="0,1,0,0"><Grid Margin="30,0"><StackPanel Orientation="Horizontal" VerticalAlignment="Center"><Button x:Name="ShortcutButton" Content="Desktop Shortcut" Padding="10,6" Margin="0,0,8,0"/><Button x:Name="MinimizeButton" Content="Minimize" Padding="10,6" Margin="0,0,8,0"/><Button x:Name="CloseButton" Content="Close Window" Padding="10,6"/></StackPanel><TextBlock x:Name="CheckedText" HorizontalAlignment="Right" VerticalAlignment="Center" Foreground="#8D99A8" FontSize="11"/></Grid></Border></Grid></Window>
'@
$window=[Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $xaml));function C($n){$window.FindName($n)}
$primary=C 'PrimaryButton';$statusLabel=C 'StatusLabel';$statusDetail=C 'StatusDetail';$statusDot=C 'StatusDot';$headerDot=C 'HeaderDot';$headerText=C 'HeaderText';$progress=C 'Progress';$login=C 'LoginButton';$activity=C 'ActivityList';$checked=C 'CheckedText';$lan=Get-Lan;$remote="http://${lan}:3000/remote"
(C 'VersionText').Text=Version-Text;(C 'RemoteUrl').Text=$remote;(C 'DisplayUrl').Text="http://${lan}:3000/?display=<display-id>"
$script:lastState='';$script:primaryMode='start';$script:operatorActivity=New-Object System.Collections.Generic.List[string]
function Add-Activity([string]$message,[string]$level='INFO'){ $script:operatorActivity.Insert(0,("{0}  {1}  {2}" -f (Get-Date -Format 'h:mm:ss tt'),$level,$message));while($script:operatorActivity.Count -gt 8){$script:operatorActivity.RemoveAt($script:operatorActivity.Count-1)} }
function Paint($title,$detail,$pill,$color){$statusLabel.Text=$title;$statusDetail.Text=$detail;$statusDot.Fill=[Windows.Media.BrushConverter]::new().ConvertFromString($color);$headerDot.Fill=$statusDot.Fill;$headerText.Text=$pill;$checked.Text="Last checked $(Get-Date -Format 'h:mm:ss tt')"}
function Set-PrimaryMode([string]$mode){$script:primaryMode=$mode;switch($mode){'stop'{$primary.Content='STOP PERFORMANCE CENTER';$primary.Background=[Windows.Media.BrushConverter]::new().ConvertFromString('#B42318');$primary.IsEnabled=$true}'setup'{$primary.Content='SET UP + START';$primary.Background=[Windows.Media.BrushConverter]::new().ConvertFromString('#0F6CBD');$primary.IsEnabled=$true}default{$primary.Content='START PERFORMANCE CENTER';$primary.Background=[Windows.Media.BrushConverter]::new().ConvertFromString('#0F6CBD');$primary.IsEnabled=$true}}}
function Refresh-Activity([bool]$online=$false,[string]$st='unknown'){$activity.Items.Clear();$backendText=if($online){'OK - Backend health check is responding'}else{'OFFLINE - Backend health check is not responding'};[void]$activity.Items.Add(("{0}  SYSTEM  {1}" -f (Get-Date -Format 'h:mm:ss tt'),$backendText));$stText=switch($st){'healthy'{'OK - ServiceTitan is connected and usable'}'login-required'{'ACTION - ServiceTitan needs a login'}'degraded'{'WARNING - ServiceTitan connection is degraded'}default{'UNKNOWN - ServiceTitan status unavailable'}};[void]$activity.Items.Add(("{0}  SYSTEM  {1}" -f (Get-Date -Format 'h:mm:ss tt'),$stText));foreach($line in $script:operatorActivity){[void]$activity.Items.Add($line)};if($script:operatorActivity.Count -eq 0){[void]$activity.Items.Add('No operator actions yet. GRMetro will report starts, stops, restarts, refreshes, and failures here.')}}
function Update-Status {$online=Test-Backend;$a=if($online){Get-Admin}else{$null};$st=ST-State $a;$state=if($online -and $st -eq 'login-required'){'login'}elseif($online){'running'}elseif(Needs-Setup){'setup'}else{'ready'};switch($state){'running'{Paint 'Running' 'Backend healthy - ServiceTitan connected - self-healing active' 'ONLINE' '#198754';Set-PrimaryMode 'stop';$login.Visibility='Collapsed'}'login'{Paint 'ServiceTitan login required' 'Backend is running, but ServiceTitan needs you to sign in.' 'ACTION NEEDED' '#D97706';Set-PrimaryMode 'stop';$login.Visibility='Visible'}'ready'{Paint 'Ready to start' 'Setup is complete. Start the supervised backend and ServiceTitan browser.' 'READY' '#D97706';Set-PrimaryMode 'start';$login.Visibility='Collapsed'}'setup'{Paint 'First-time setup needed' 'Set up and start GRMetro.' 'SETUP' '#D97706';Set-PrimaryMode 'setup';$login.Visibility='Collapsed'}};Refresh-Activity $online $st}
function Busy($text){$progress.Visibility='Visible';$statusLabel.Text=$text;$primary.IsEnabled=$false;$window.Dispatcher.Invoke([action]{},'Background')}
function Done($detail,$text){$detail.Text="Done - $text";Add-Activity $text 'SUCCESS';Show-GrMetroResult -Title 'GRMetro Performance Center' -Message $text -Success $true;Update-Status}
function Stop-GRMetro {if(-not(Confirm-GrMetroAction 'Stop GRMetro' 'Are you sure you want to stop the Performance Center? This stops the supervisor, backend, and dedicated ServiceTitan browser.')){return};try{Busy 'Stopping...';Add-Activity 'Stopping Performance Center...' 'WORKING';if((Run-HiddenWait $stopScript)-ne 0){throw 'Stop command failed.'};Add-Activity 'Performance Center stopped successfully.' 'SUCCESS';Show-GrMetroResult 'GRMetro stopped' 'Performance Center is stopped. You can start it again from this same button.' $true}catch{Add-Activity ("Stop failed: {0}" -f $_.Exception.Message) 'ERROR';Show-GrMetroResult 'Stop failed' $_.Exception.Message $false}finally{$progress.Visibility='Collapsed';Update-Status}}
$primary.Add_Click({if($script:primaryMode -eq 'stop'){Stop-GRMetro;return};try{if(Needs-Setup){Busy 'Setting up...';Add-Activity 'Running first-time setup...' 'WORKING';if((Run-HiddenWait $setupScript)-ne 0){throw 'Setup did not complete.'}};Busy 'Starting...';Add-Activity 'Starting Performance Center...' 'WORKING';Start-Supervisor;if(-not(Wait-Backend $true 40)){throw 'Backend did not become healthy.'};Add-Activity 'Performance Center started and backend is healthy.' 'SUCCESS';Show-GrMetroResult 'GRMetro Performance Center' 'Performance Center started successfully.' $true}catch{Add-Activity ("Start failed: {0}" -f $_.Exception.Message) 'ERROR';Show-GrMetroResult 'Start failed' $_.Exception.Message $false}finally{$progress.Visibility='Collapsed';Update-Status}})
$login.Add_Click({Start-Process powershell.exe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File',('"{0}"' -f $edgeScript)) -WorkingDirectory $root -WindowStyle Hidden|Out-Null;Add-Activity 'Opened dedicated ServiceTitan login session.' 'INFO';Update-Status})
(C 'RemoteButton').Add_Click({Show-NativeRemoteAccess -RemoteUrl $remote -Root $root})
(C 'AdminButton').Add_Click({Show-NativeDiagnostics})
(C 'LogsButton').Add_Click({Show-NativeRecoveryLogs -LogPath $logPath})
(C 'RefreshButton').Add_Click({$d=C 'RefreshDetail';try{Busy 'Refreshing data...';$d.Text='Refreshing...';Add-Activity 'Refreshing ServiceTitan data...' 'WORKING';Invoke-RestMethod -Method Post -Uri 'http://127.0.0.1:3000/api/v1/management/refresh' -TimeoutSec 60|Out-Null;Done $d 'ServiceTitan data refresh completed.'}catch{$d.Text='Refresh failed';Add-Activity ("Data refresh failed: {0}" -f $_.Exception.Message) 'ERROR';Show-GrMetroResult 'Refresh failed' $_.Exception.Message $false}finally{$progress.Visibility='Collapsed';Update-Status}})
(C 'RestartBackendButton').Add_Click({$d=C 'BackendDetail';if(-not(Confirm-GrMetroAction 'Restart Backend' 'Are you sure you want to restart the GRMetro backend? The supervisor will bring it back automatically.')){return};try{Busy 'Restarting backend...';$d.Text='Restarting...';Add-Activity 'Restarting backend...' 'WORKING';if((Run-HiddenWait $controlScript @('restart-backend'))-ne 0){throw 'Restart command failed.'};if(-not(Wait-Backend $true 45)){throw 'Backend did not return healthy within 45 seconds.'};Done $d 'Backend restarted and health check passed.'}catch{$d.Text='Restart failed';Add-Activity ("Backend restart failed: {0}" -f $_.Exception.Message) 'ERROR';Show-GrMetroResult 'Backend restart failed' $_.Exception.Message $false}finally{$progress.Visibility='Collapsed';Update-Status}})
(C 'RestartBrowserButton').Add_Click({$d=C 'BrowserDetail';if(-not(Confirm-GrMetroAction 'Restart ServiceTitan' 'Are you sure you want to restart the dedicated ServiceTitan browser session? Your normal Edge windows will not be touched.')){return};try{Busy 'Restarting ServiceTitan...';$d.Text='Restarting dedicated Edge...';Add-Activity 'Restarting dedicated ServiceTitan session...' 'WORKING';if((Run-HiddenWait $controlScript @('restart-browser'))-ne 0){throw 'ServiceTitan restart command failed.'};$end=(Get-Date).AddSeconds(45);$healthy=$false;do{Start-Sleep -Milliseconds 750;[System.Windows.Forms.Application]::DoEvents();$a=Get-Admin;if($a -and (ST-State $a)-eq 'healthy'){$healthy=$true;break}}while((Get-Date)-lt $end);if(-not$healthy){throw 'ServiceTitan did not reconnect within 45 seconds.'};Done $d 'ServiceTitan restarted and connection verified.'}catch{$d.Text='Restart failed';Add-Activity ("ServiceTitan restart failed: {0}" -f $_.Exception.Message) 'ERROR';Show-GrMetroResult 'ServiceTitan restart failed' $_.Exception.Message $false}finally{$progress.Visibility='Collapsed';Update-Status}})
(C 'ConfigButton').Add_Click({try{$code=Run-HiddenWait $wizardScript @('-Force');if($code -eq 0){Add-Activity 'Deployment configuration saved.' 'SUCCESS';Show-GrMetroResult 'Configuration saved' 'Deployment configuration was saved successfully. Restart the backend if you changed ServiceTitan or timezone settings.' $true}else{Add-Activity 'Configuration window closed without saving.' 'INFO';Show-GrMetroResult 'Configuration' 'Configuration was cancelled.' $true}}catch{Add-Activity ("Configuration failed: {0}" -f $_.Exception.Message) 'ERROR';Show-GrMetroResult 'Configuration failed' $_.Exception.Message $false};Update-Status})
(C 'UpdateButton').Add_Click({try{Busy 'Checking for updates...';Add-Activity 'Checking for GRMetro updates...' 'WORKING';$out=& powershell.exe -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File $updateScript -CheckOnly|Select-Object -Last 1;$r=$out|ConvertFrom-Json;if($r.updateAvailable){if(Confirm-GrMetroAction 'Install Update' "$($r.message)`n`nInstall now? Tests and a build will run before restart."){if((Run-HiddenWait $updateScript)-ne 0){throw 'Update failed.'};Add-Activity 'GRMetro update installed successfully.' 'SUCCESS';Show-GrMetroResult 'Update complete' 'GRMetro was updated successfully.' $true}else{Add-Activity 'Available update was not installed.' 'INFO'}}else{Add-Activity 'Update check complete; no update required.' 'SUCCESS';Show-GrMetroResult 'Updates' $r.message $true}}catch{Add-Activity ("Update check/install failed: {0}" -f $_.Exception.Message) 'ERROR';Show-GrMetroResult 'Update failed' $_.Exception.Message $false}finally{$progress.Visibility='Collapsed';Update-Status}})
(C 'FolderButton').Add_Click({Start-Process explorer.exe -ArgumentList ('"{0}"' -f $root)})
(C 'ShortcutButton').Add_Click({$exe=Join-Path $root 'GRMetro Performance Center.exe';$target=if(Test-Path $exe){$exe}else{Join-Path $root 'GRMetro Performance Center.cmd'};$s=New-Object -ComObject WScript.Shell;$lnk=$s.CreateShortcut((Join-Path ([Environment]::GetFolderPath('Desktop')) 'GRMetro Performance Center.lnk'));$lnk.TargetPath=$target;$lnk.WorkingDirectory=$root;$lnk.Save();Add-Activity 'Desktop shortcut created.' 'SUCCESS';Show-GrMetroResult 'Desktop Shortcut' 'Desktop shortcut created.' $true;Update-Status})
(C 'MinimizeButton').Add_Click({$window.WindowState='Minimized'});(C 'CloseButton').Add_Click({$window.Hide()});$window.Add_Closing({param($s,$e){$e.Cancel=$true;$window.Hide()}})
$timer=New-Object System.Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromSeconds(5);$timer.Add_Tick({Update-Status});$timer.Start();Update-Status
if($AutoStart -and -not(Test-Backend)){$window.Add_ContentRendered({$primary.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Button]::ClickEvent)))})}
[void]$window.ShowDialog();$timer.Stop()
